package kr.ac.kdu.focurve;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import jakarta.servlet.http.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
import org.springframework.security.crypto.argon2.Argon2PasswordEncoder;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import static kr.ac.kdu.focurve.MemberIntervals.*;

@org.springframework.context.annotation.Profile("member-runtime | local-integration")
@Component
class MemberAuth {
 static class LoginBucket {final java.util.ArrayDeque<Long> failures=new java.util.ArrayDeque<>();int pending;}
 final java.util.concurrent.ConcurrentHashMap<String,LoginBucket> failures=new java.util.concurrent.ConcurrentHashMap<>();
 void loginBegin(String key){var b=failures.computeIfAbsent(key,k->new LoginBucket());synchronized(b){long cutoff=System.currentTimeMillis()-60000;while(!b.failures.isEmpty()&&b.failures.getFirst()<cutoff)b.failures.removeFirst();check(b.failures.size()+b.pending<5,429,"LOGIN_RATE_LIMITED");b.pending++;}}
 void loginFinish(String key,boolean failed){var b=failures.get(key);synchronized(b){b.pending--;if(failed)b.failures.addLast(System.currentTimeMillis());}}
 @Value("${member.same-owner-recovery-enabled:false}") boolean sameOwnerRecoveryEnabled;
 @Value("${FOCURVE_PRESERVED_END_GRANT:}") String preservedEndGrant="";
 @Value("${FOCURVE_PRESERVED_END_GRANT_SHA256:}") String preservedEndSHA="";
 @Value("${FOCURVE_AUTH_RECOVERY_GRANT:}") String recoveryGrant="";
 @Value("${FOCURVE_AUTH_RECOVERY_GRANT_SHA256:}") String recoveryGrantSHA="";
 @Value("${FOCURVE_INSTALLATION_GATE:}") String recoveryGate="";
 final JdbcTemplate db;final ObjectMapper json;final String origin;final Set<String> callbacks;final byte[] encryptionKey;final Argon2PasswordEncoder passwords=Argon2PasswordEncoder.defaultsForSpringSecurity_v5_8();
 MemberAuth(JdbcTemplate db,ObjectMapper json,@Value("${member.origin}")String origin,@Value("${member.link-key}")String key,@Value("${member.callbacks}")String callbacks){this.db=db;this.json=json;this.origin=origin;this.callbacks=Set.of(callbacks.split(","));encryptionKey=Base64.getDecoder().decode(key);require(encryptionKey.length==32,"LINK_KEY_REQUIRED");}
 static class Failure extends RuntimeException{final int status;final String code;Failure(int s,String c){super(c);status=s;code=c;}}
 static void check(boolean b,int s,String c){if(!b)throw new Failure(s,c);}
 static String id(){return UUID.randomUUID().toString();}
 static String secret(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}
 static String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 static Timestamp now(){return Timestamp.from(Instant.now());}static Timestamp after(long seconds){return Timestamp.from(Instant.now().plusSeconds(seconds));}
 static boolean future(Object t){Instant at=t instanceof Timestamp v?v.toInstant():t instanceof java.time.LocalDateTime v?v.toInstant(java.time.ZoneOffset.UTC):null;return at!=null&&at.isAfter(Instant.now());}
 static String instant(Object t){if(t instanceof Timestamp v)return v.toInstant().toString();if(t instanceof java.time.LocalDateTime v)return v.toInstant(java.time.ZoneOffset.UTC).toString();throw new IllegalArgumentException("INVALID_DATABASE_TIME");}
 Map<String,Object> one(String sql,Object...args){var rows=db.queryForList(sql,args);return rows.isEmpty()?null:rows.getFirst();}
 ObjectNode obj(Object...pairs){ObjectNode n=json.createObjectNode();for(int i=0;i<pairs.length;i+=2)n.set((String)pairs[i],json.valueToTree(pairs[i+1]));return n;}
 String crypt(String value,boolean encrypt){try{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");if(encrypt){byte[]iv=new byte[12];new SecureRandom().nextBytes(iv);c.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(encryptionKey,"AES"),new GCMParameterSpec(128,iv));byte[]x=c.doFinal(value.getBytes(StandardCharsets.UTF_8));byte[]r=Arrays.copyOf(iv,iv.length+x.length);System.arraycopy(x,0,r,iv.length,x.length);return Base64.getEncoder().encodeToString(r);}byte[]all=Base64.getDecoder().decode(value);c.init(Cipher.DECRYPT_MODE,new SecretKeySpec(encryptionKey,"AES"),new GCMParameterSpec(128,Arrays.copyOf(all,12)));return new String(c.doFinal(Arrays.copyOfRange(all,12,all.length)),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("LINK_CIPHER_FAILURE");}}
 String cookie(HttpServletRequest r){if(r.getCookies()!=null)for(Cookie c:r.getCookies())if(c.getName().equals("FOCURVE_WEB"))return c.getValue();return "";}
 Map<String,Object> web(HttpServletRequest r,boolean mutation,boolean login){Map<String,Object>w=one("SELECT * FROM web_sessions WHERE id_hash=? AND (user_id IS NULL OR auth_version=(SELECT auth_version FROM users WHERE users.id=web_sessions.user_id)) FOR UPDATE",hash(cookie(r)));check(w!=null&&future(w.get("expires_at")),401,"UNAUTHENTICATED");if(mutation)check(origin.equals(r.getHeader("Origin"))&&hash(Objects.toString(r.getHeader("X-CSRF-Token"),"")).equals(w.get("csrf_hash")),403,"CSRF_REJECTED");if(login)check(w.get("user_id")!=null,401,"UNAUTHENTICATED");return w;}
 void setCookie(HttpServletResponse r,String value){r.addHeader("Set-Cookie","FOCURVE_WEB="+value+"; Path=/; HttpOnly; Secure; SameSite=Lax");}
 ObjectNode csrf(HttpServletRequest r,HttpServletResponse response){var existing=one("SELECT * FROM web_sessions WHERE id_hash=? AND (user_id IS NULL OR auth_version=(SELECT auth_version FROM users WHERE users.id=web_sessions.user_id)) FOR UPDATE",hash(cookie(r)));if(existing!=null&&future(existing.get("expires_at"))){String rotated=kr.ac.kdu.focurve.auth.AuthSupport.fingerprint(cookie(r),"FOCURVE_CSRF_V1");db.update("UPDATE web_sessions SET csrf_hash=? WHERE id_hash=?",hash(rotated),existing.get("id_hash"));return obj("csrf_token",rotated);}String sid=secret(),csrf=kr.ac.kdu.focurve.auth.AuthSupport.fingerprint(sid,"FOCURVE_CSRF_V1");db.update("INSERT INTO web_sessions(id_hash,user_id,csrf_hash,expires_at) VALUES(?,NULL,?,?)",hash(sid),hash(csrf),after(3600));setCookie(response,sid);return obj("csrf_token",csrf);}
 ObjectNode login(HttpServletRequest req,HttpServletResponse response,JsonNode b){var w=web(req,true,false);String email=text(b,"email").trim().toLowerCase(Locale.ROOT),account="account:"+hash(email),ip="ip:"+hash(req.getRemoteAddr());loginBegin(account);try{loginBegin(ip);}catch(RuntimeException error){loginFinish(account,false);throw error;}boolean failed=false;try{var row=one("SELECT i.password_hash,u.* FROM auth_identities i JOIN users u ON i.user_id=u.id WHERE i.provider='EMAIL' AND i.subject=? FOR UPDATE",email);if(row==null||!passwords.matches(text(b,"password"),row.get("password_hash").toString())){failed=true;throw new Failure(401,"INVALID_CREDENTIALS");}check(Boolean.TRUE.equals(row.get("email_verified")),403,"EMAIL_UNVERIFIED");check("ACTIVE".equals(row.get("status")),401,"UNAUTHENTICATED");String sid=secret(),csrf=kr.ac.kdu.focurve.auth.AuthSupport.fingerprint(sid,"FOCURVE_CSRF_V1");db.update("DELETE FROM web_sessions WHERE id_hash=?",w.get("id_hash"));db.update("INSERT INTO web_sessions(id_hash,user_id,csrf_hash,expires_at,auth_version) VALUES(?,?,?,?,?)",hash(sid),row.get("id"),hash(csrf),after(3600),row.get("auth_version"));setCookie(response,sid);return obj("user_id",row.get("id").toString(),"display_name",row.get("display_name"),"email",row.get("email"),"email_verified",true,"providers",List.of("EMAIL"),"csrf_token",csrf);}finally{loginFinish(account,failed);loginFinish(ip,failed);}}
 record Identity(long user,String executor){}
 Identity identity(HttpServletRequest req,boolean mutate){String bearer=req.getHeader("Authorization");if(bearer!=null){check(bearer.startsWith("Bearer "),401,"UNAUTHENTICATED");var t=one("SELECT t.* FROM extension_tokens t JOIN extension_installations i ON i.id=t.executor_id AND i.current_user_id=t.user_id WHERE t.access_hash=? AND t.revoked_at IS NULL AND t.access_expires_at>CURRENT_TIMESTAMP(3) AND t.auth_version=(SELECT auth_version FROM users WHERE users.id=t.user_id) FOR UPDATE",hash(bearer.substring(7)));check(t!=null,401,"UNAUTHENTICATED");return new Identity(((Number)t.get("user_id")).longValue(),t.get("executor_id").toString());}var w=web(req,mutate,true);return new Identity(((Number)w.get("user_id")).longValue(),null);}
 void installation(HttpServletRequest req,String executor){uuid(executor);var i=one("SELECT * FROM extension_installations WHERE id=? FOR UPDATE",executor);check(i!=null&&i.get("proof_hash").equals(hash(Objects.toString(req.getHeader("X-Installation-Proof"),""))),401,"INVALID_INSTALLATION");}
 ObjectNode install(JsonNode b){uuid(text(b,"executor_id"));String version=text(b,"client_version");check(!version.isBlank()&&version.length()<=40,422,"VALIDATION_FAILED");String proof=secret();check(one("SELECT id FROM extension_installations WHERE id=?",text(b,"executor_id"))==null,409,"INSTALLATION_EXISTS");db.update("INSERT INTO extension_installations VALUES(?,NULL,?,?,?)",text(b,"executor_id"),hash(proof),version,now());return obj("executor_id",text(b,"executor_id"),"installation_proof",proof);}
 ObjectNode link(HttpServletRequest req,JsonNode b){String ex=text(b,"executor_id");installation(req,ex);String callback=text(b,"callback_uri"),challenge=text(b,"code_challenge"),state=text(b,"state");check(callback.matches("chrome-extension://[a-p]{32}/popup/popup\\.html")&&callbacks.contains(callback),422,"INVALID_CALLBACK");check(challenge.matches("[A-Za-z0-9_-]{43}")&&state.length()>=32&&state.length()<=128,422,"INVALID_PKCE");String id=id();ObjectNode recovery=SameOwnerRecovery.begin(this,b,ex,id);db.update("INSERT INTO link_requests(id,executor_id,code_challenge,callback_uri,state_hash,expires_at) VALUES(?,?,?,?,?,?)",id,ex,challenge,callback,hash(state),after(300));if(recovery!=null)db.update("UPDATE link_requests SET execution_evidence=? WHERE id=?",obj(SameOwnerRecovery.KEY,recovery).toString(),id);return obj("link_request_id",id,"verification_uri",origin+"/#link?id="+id,"expires_at",after(300).toInstant().toString());}
 ObjectNode linkAction(HttpServletRequest req,String id,String action,JsonNode b){uuid(id);var l=one("SELECT * FROM link_requests WHERE id=? FOR UPDATE",id);check(l!=null&&future(l.get("expires_at"))&&l.get("consumed_at")==null,410,"LINK_EXPIRED");String ex=l.get("executor_id").toString();
  if(action.equals("approval")){var w=web(req,true,true);check(b.path("approve").isBoolean(),422,"VALIDATION_FAILED");check(b.path("approve").asBoolean(),409,"LINK_REJECTED");check(l.get("execution_evidence")!=null,409,"EXECUTION_EVIDENCE_REQUIRED");SameOwnerRecovery.validate(this,l,((Number)w.get("user_id")).longValue());installationOwnerSafe(ex,((Number)w.get("user_id")).longValue());String code=secret();db.update("UPDATE link_requests SET approved_user_id=?,approved_auth_version=?,code_hash=?,code_cipher=?,code_expires_at=? WHERE id=?",w.get("user_id"),w.get("auth_version"),hash(code),crypt(code,true),after(60),id);db.update("UPDATE web_sessions SET logout_executor_id=? WHERE id_hash=?",ex,w.get("id_hash"));return obj("status","APPROVED");}
  installation(req,ex);if(action.equals("evidence")){check(b.has("active_session_id")&&b.get("active_session_id").isNull()&&b.path("pending_action_count").asInt(-1)==0&&b.path("owned_rule_ids").isArray()&&b.path("owned_rule_ids").isEmpty()&&text(b,"owner_context").equals("GUEST:"+ex),409,"EXECUTION_EVIDENCE_REQUIRED");db.update("UPDATE link_requests SET execution_evidence=? WHERE id=?",SameOwnerRecovery.evidence(this,l,b).toString(),id);return obj("accepted",true);}
  check(action.equals("claim")&&hash(text(b,"state")).equals(l.get("state_hash")),401,"INVALID_STATE");if(l.get("approved_user_id")==null)return obj("status","PENDING");check(future(l.get("code_expires_at")),410,"LINK_EXPIRED");approvalGeneration(l);return obj("status","APPROVED","state",text(b,"state"),"code",crypt(l.get("code_cipher").toString(),false));
 }
 void installationOwnerSafe(String ex,long user){var i=one("SELECT * FROM extension_installations WHERE id=? FOR UPDATE",ex);check(i.get("current_user_id")==null||((Number)i.get("current_user_id")).longValue()==user,409,"OWNER_CONFLICT");check(one("SELECT user_id FROM active_execution_locks WHERE executor_id=?",ex)==null,409,"RELEASE_UNCONFIRMED");}
 long authVersion(long user){Long value=db.queryForObject("SELECT auth_version FROM users WHERE id=?",Long.class,user);check(value!=null&&value>0,401,"UNAUTHENTICATED");return value;}
 long approvalGeneration(Map<String,Object> l){check(l.get("approved_auth_version") instanceof Number&&l.get("approved_user_id") instanceof Number,401,"INVALID_GRANT");long version=((Number)l.get("approved_auth_version")).longValue();check(version>0&&version==authVersion(((Number)l.get("approved_user_id")).longValue()),401,"INVALID_GRANT");return version;}
 ObjectNode mint(String ex,long user,String family,long generation){check(generation>0&&generation==authVersion(user),401,"INVALID_GRANT");String access=secret(),refresh=secret();db.update("INSERT INTO extension_tokens(id,executor_id,user_id,refresh_hash,access_hash,family_id,expires_at,access_expires_at,revoked_at,auth_version) VALUES(?,?,?,?,?,?,?,?,NULL,?)",id(),ex,user,hash(refresh),hash(access),family,after(2592000),after(900),generation);return obj("access_token",access,"refresh_token",refresh,"expires_in",900);}
 ObjectNode token(HttpServletRequest req,JsonNode b){var l=one("SELECT * FROM link_requests WHERE id=? FOR UPDATE",text(b,"link_request_id"));check(l!=null,401,"INVALID_GRANT");String ex=l.get("executor_id").toString();installation(req,ex);String verifier=text(b,"code_verifier");check(verifier.matches("[A-Za-z0-9._~-]{43,128}"),401,"INVALID_GRANT");String challenge;try{challenge=Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}
  check(l.get("consumed_at")==null&&l.get("approved_user_id")!=null&&future(l.get("expires_at"))&&future(l.get("code_expires_at"))&&hash(text(b,"code")).equals(l.get("code_hash"))&&challenge.equals(l.get("code_challenge")),401,"INVALID_GRANT");long user=((Number)l.get("approved_user_id")).longValue();long generation=approvalGeneration(l);installationOwnerSafe(ex,user);db.update("UPDATE extension_installations SET current_user_id=? WHERE id=?",user,ex);db.update("UPDATE link_requests SET consumed_at=?,code_cipher=NULL WHERE id=?",now(),text(b,"link_request_id"));SameOwnerRecovery.retire(this,l,user);return mint(ex,user,id(),generation);}
 ObjectNode refresh(JsonNode b){var t=one("SELECT * FROM extension_tokens WHERE refresh_hash=? FOR UPDATE",hash(text(b,"refresh_token")));check(t!=null&&future(t.get("expires_at")),401,"INVALID_GRANT");check(t.get("auth_version") instanceof Number&&((Number)t.get("auth_version")).longValue()==authVersion(((Number)t.get("user_id")).longValue()),401,"INVALID_GRANT");var i=one("SELECT * FROM extension_installations WHERE id=? FOR UPDATE",t.get("executor_id"));check(Objects.equals(i.get("current_user_id"),t.get("user_id")),401,"INVALID_GRANT");if(t.get("revoked_at")!=null){db.update("UPDATE extension_tokens SET revoked_at=COALESCE(revoked_at,?) WHERE family_id=?",now(),t.get("family_id"));return obj("_error","TOKEN_REUSE");}db.update("UPDATE extension_tokens SET revoked_at=? WHERE id=?",now(),t.get("id"));return mint(t.get("executor_id").toString(),((Number)t.get("user_id")).longValue(),t.get("family_id").toString(),((Number)t.get("auth_version")).longValue());}
}
